head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > E > onchange]<br/>Multiselect 컴포넌트에서 아이템의 선택이 변경되면 발생합니다.",
    "validation" : [
        "setValue() 메소드에 의해 아이템 선택이 변경된 경우 onchange 이벤트가 발생합니다.",
        "setText() 메소드에 의해 아이템 선택이 변경된 경우 onchange 이벤트가 발생합니다.",
        "setSelectedIndex() 메소드에 의해 아이템 선택이 변경된 경우 onchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// onchange 이벤트 핸들러 — 파라미터 없음
scwin.target1_onchange = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createDataListMultiSelect();

    let cList = $c.gcm.createCList({ separator: "," });
    let eHandler = 'ev:onchange="scwin.target1_onchange"';

    await $c.gcm.createBasicMultiSelect(cList, eHandler);
}



// setValue 호출 - 메소드에 의해 onchange 발생 검증
scwin.btn_setValue_onclick = function (e) {
    let v = par_value.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setValue('" + v + "') 호출 ▶");
    target1.setValue(v);
};



// setText 호출 - 메소드에 의해 onchange 발생 검증
scwin.btn_setText_onclick = function (e) {
    let t = par_label.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setText('" + t + "') 호출 ▶");
    target1.setText(t);
};



// setSelectedIndex 호출 - 메소드에 의해 onchange 발생 검증
scwin.btn_setSelectedIndex_onclick = function (e) {
    let idx = par_index.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setSelectedIndex('" + idx + "') 호출 ▶");
    target1.setSelectedIndex(idx);
};
